function validate([nums, k, m]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 2000) return 'nums holds 1 to 2000 numbers.';
  if (nums.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each number is a whole number from -10^4 to 10^4.';
  if (!Number.isInteger(m) || m < 1 || m > 3) return 'm is 1, 2 or 3.';
  if (!Number.isInteger(k) || k < 1 || k > Math.floor(nums.length / m)) return 'k is between 1 and floor(nums.length / m).';
  return null;
}

