function maxSum(nums, k, m) {
  const n = nums.length;
  const prefix = new Array(n + 1).fill(0);
  for (let j = 0; j < n; j++) {
    prefix[j + 1] = prefix[j] + nums[j];
  }
  let previous = new Array(n + 1).fill(0);
  for (let i = 1; i <= k; i++) {
    const current = new Array(n + 1).fill(-Infinity);
    let best = -Infinity;
    for (let j = i * m; j <= n; j++) {
      best = Math.max(best, previous[j - m] - prefix[j - m]);
      current[j] = Math.max(current[j - 1], best + prefix[j]);
    }
    previous = current;
  }
  return previous[n];
}

