function maxSum(nums, k, m) {
  const n = nums.length;
  const memo = new Map();
  // most(start, left): the best total of left more subarrays taken from nums[start..].
  const most = (start, left) => {
    if (left === 0) return 0;
    if (n - start < left * m) return -Infinity;
    const key = start * (k + 1) + left;
    if (memo.has(key)) return memo.get(key);
    // Either nums[start] is left out, or a subarray nums[start..end] of length at least m starts here.
    let result = most(start + 1, left);
    let sum = 0;
    for (let end = start; end < n; end++) {
      sum += nums[end];
      if (end - start + 1 >= m) result = Math.max(result, sum + most(end + 1, left - 1));
    }
    memo.set(key, result);
    return result;
  };
  return most(0, k);
}

