function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(1800, 2000) : int(1, 10);
  const m = int(1, Math.min(3, n));
  const most = Math.floor(n / m);
  // k is sometimes 1, sometimes as large as allowed (every subarray tight), and otherwise anything in between.
  const pick = rand();
  const k = pick < 0.25 ? 1 : pick < 0.5 ? most : int(1, most);
  const limit = large ? 10000 : [3, 10, 10000][int(0, 2)];
  // The bias makes some inputs mostly negative and some mostly positive.
  const bias = rand() < 0.3 ? -1 : rand() < 0.5 ? 1 : 0;
  const nums = Array.from({ length: n }, () => {
    const value = int(-limit, limit);
    return bias !== 0 && rand() < 0.7 ? bias * Math.abs(value) : value;
  });
  return [nums, k, m];
}
